def write_zone_naming_library(tmp_path: Path) -> None:
    """把這 5 筆寫成網頁讀的材料庫檔（內建材料照樣在，地毯、門窗分組照產品規則算）。"""
    adapter: TypeAdapter[tuple[LibraryEntry, ...]] = TypeAdapter(tuple[LibraryEntry, ...])
    (tmp_path / "materials.json").write_text(dump_user_library(adapter.validate_python(ZONE_NAMING_LIBRARY)), encoding="utf-8")
